import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Gemini 全家族","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/index.md","filePath":"zh/products/ai-coding/gemini/index.md","lastUpdated":1787044708000}'),i={name:"zh/products/ai-coding/gemini/index.md"};function l(r,a,o,d,p,h){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="gemini-全家族" tabindex="-1">Gemini 全家族 <a class="header-anchor" href="#gemini-全家族" aria-label="Permalink to &quot;Gemini 全家族&quot;">​</a></h1><blockquote><p>Google 的 AI 编码与创意产品线。这一页是<strong>产品全景 + 决策树</strong>：先回答「我要做什么 → 用哪个」，再进各产品页。</p><p><strong>2026-06-18 起</strong>：个人账号、Google AI Pro / Ultra 通过「Login with Google」访问 <a href="./gemini-cli.html">Gemini CLI</a> 与 <a href="./code-assist.html">Code Assist</a> IDE 扩展已停服，请改用 <a href="./antigravity.html">Antigravity</a> 家族。Standard / Enterprise 许可证与付费 API key 不受影响。官方说明见 <a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">消费者账号弃用</a> 与 <a href="https://developers.googleblog.com/an-important-update-transitioning-gemini-cli-to-antigravity-cli" target="_blank" rel="noreferrer">过渡公告</a>。</p></blockquote><h2 id="产品全景图" tabindex="-1">产品全景图 <a class="header-anchor" href="#产品全景图" aria-label="Permalink to &quot;产品全景图&quot;">​</a></h2><p>编码主线按「谁在驾驶」切开；影像与原型对位 Claude 家族里的 Design，不和终端抢位置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gemini 全家族</span></span>
<span class="line"><span>├── 编码主线（谁在驾驶）</span></span>
<span class="line"><span>│   ├── 你逐字敲，AI 补全              → Code Assist</span></span>
<span class="line"><span>│   ├── 你下指令，AI 在你终端里执行      → Gemini CLI</span></span>
<span class="line"><span>│   ├── 你定目标，AI 自己规划执行        → Antigravity</span></span>
<span class="line"><span>│   └── 你交任务，AI 在云端做完给你 PR   → Jules</span></span>
<span class="line"><span>├── 原型与影像（对位 Claude Design）</span></span>
<span class="line"><span>│   ├── 能点的交互原型                 → Canvas</span></span>
<span class="line"><span>│   └── 落地页 / 宣传片 / 产品演示视频   → Google Flow</span></span>
<span class="line"><span>├── 模型与订阅</span></span>
<span class="line"><span>│   ├── 调模型、走 API                 → AI Studio</span></span>
<span class="line"><span>│   └── 付费档与额度                   → Google AI 订阅</span></span>
<span class="line"><span>└── Pro 订阅还带、不必独立成页</span></span>
<span class="line"><span>    ├── Gemini Spark（US、个人 agent）</span></span>
<span class="line"><span>    ├── Gemini Notebook（研究 / 写作）</span></span>
<span class="line"><span>    ├── Gemini app + Deep Research</span></span>
<span class="line"><span>    ├── Gemini in Chrome auto browse（US）</span></span>
<span class="line"><span>    ├── Gemini in Android Studio</span></span>
<span class="line"><span>    └── Google Flow Music（flowmusic.app，积分与 Flow 分开）</span></span></code></pre></div><p>Dreambeans、Health Premium、Home Premium、TV Create Hub、Earth、Photos Remix 也在同一份订阅里，<strong>与编码无关</strong>，本站不写。一行说明见 <a href="./google-pro.html#订阅还带什么">订阅页</a>。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 写代码 / 调试 / 重构 / 提 PR</span></span>
<span class="line"><span>│   ├── 在终端、要进管道？</span></span>
<span class="line"><span>│   │   ├── 个人账号 → Antigravity CLI</span></span>
<span class="line"><span>│   │   └── Standard / Enterprise 或 API key → Gemini CLI</span></span>
<span class="line"><span>│   ├── 跨模块、要边看边验证？ → Antigravity</span></span>
<span class="line"><span>│   ├── 边界清晰、丢出去等 PR？ → Jules</span></span>
<span class="line"><span>│   └── 不想离开 IDE、或团队有合规硬要求？ → Code Assist</span></span>
<span class="line"><span>├── 交互原型 / 能点的页面</span></span>
<span class="line"><span>│   └── → Canvas</span></span>
<span class="line"><span>│       └── 选定方向之后 → Antigravity 写进仓库</span></span>
<span class="line"><span>├── 落地页宣传片 / 产品演示视频 / 分镜</span></span>
<span class="line"><span>│   └── → Google Flow</span></span>
<span class="line"><span>│       └── 歌曲 / MV → Flow Music（积分分开，不必单独学）</span></span>
<span class="line"><span>├── 调温度、固化系统提示、大规模上下文、接 API</span></span>
<span class="line"><span>│   └── → AI Studio</span></span>
<span class="line"><span>└── 决定订哪一档、额度够不够</span></span>
<span class="line"><span>    └── → Google AI 订阅（表只在速查表）</span></span></code></pre></div><p>完整对照表见<a href="./gemini-cheatsheet.html#选哪个工具">速查表</a>。</p><h2 id="核心产品" tabindex="-1">核心产品 <a class="header-anchor" href="#核心产品" aria-label="Permalink to &quot;核心产品&quot;">​</a></h2><p>Tutorial 默认展开。Cookbook 紧跟核心产品，也默认展开。</p><table tabindex="0"><thead><tr><th>产品</th><th>一句话</th><th>什么时候用</th></tr></thead><tbody><tr><td><a href="./gemini-cli.html">Gemini CLI</a></td><td>终端里的 AI 智能体</td><td>想把 AI 接进管道和脚本；家族的概念入口</td></tr><tr><td><a href="./antigravity.html">Antigravity</a></td><td>agent-first 开发平台</td><td>跨模块大改动，需要边看边验证</td></tr><tr><td><a href="./jules.html">Jules</a></td><td>云端异步编码智能体</td><td>边界清晰的耗时任务，丢出去等 PR</td></tr><tr><td><a href="./gemini-cookbook.html">Cookbook</a></td><td>按「我想做什么」查配方</td><td>学完主教程之后动手</td></tr></tbody></table><h2 id="更多产品与扩展" tabindex="-1">更多产品与扩展 <a class="header-anchor" href="#更多产品与扩展" aria-label="Permalink to &quot;更多产品与扩展&quot;">​</a></h2><p>默认折叠。轴 A 不依赖前面概念；轴 B 按前端工程师相关度排——<a href="./flow.html">Flow</a> 对位 Claude Design，和 <a href="./canvas.html">Canvas</a> 放在一起。</p><table tabindex="0"><thead><tr><th>产品</th><th>一句话</th><th>什么时候用</th></tr></thead><tbody><tr><td><a href="./canvas.html">Canvas</a></td><td>对话旁边的交互式工作区</td><td>快速做能点的原型</td></tr><tr><td><a href="./flow.html">Google Flow</a></td><td>AI 创意工作室（Veo 3.1 / Nano Banana / Gemini Omni）</td><td>落地页、宣传片、产品演示视频</td></tr><tr><td><a href="./code-assist.html">Code Assist</a></td><td>IDE 集成扩展</td><td>不想换编辑器；团队有合规硬要求</td></tr><tr><td><a href="./ai-studio.html">AI Studio</a></td><td>模型与参数控制台</td><td>调温度、固化系统提示词、大规模上下文审计、接 API</td></tr><tr><td><a href="./google-pro.html">Google AI 订阅</a></td><td>付费层级与额度</td><td>决定要为哪一档付费；Pro 权益画进家族图</td></tr></tbody></table><h2 id="速查与参考" tabindex="-1">速查与参考 <a class="header-anchor" href="#速查与参考" aria-label="Permalink to &quot;速查与参考&quot;">​</a></h2><p>Cheatsheet / Glossary 默认展开。共享表只写一份，其他页只链过来。</p><table tabindex="0"><thead><tr><th>页面</th><th>用途</th></tr></thead><tbody><tr><td><a href="./gemini-cheatsheet.html">速查表</a></td><td>决策表、模型现状、订阅层级、配置路径</td></tr><tr><td><a href="./gemini-glossary.html">术语表</a></td><td>Rules / Skill / Subagent / Artifact / Flow 等概念到底指什么</td></tr></tbody></table><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><p>排列按<strong>概念依赖（轴 A）<strong>加</strong>受众复杂度（轴 B）</strong>，不是字母序，也不是热度：</p><ol><li><strong>先学 <a href="./gemini-cli.html">Gemini CLI</a></strong>。它是家族里唯一零前置的完整工具，而且首次引入了 <code>.gemini/settings.json</code>、<code>gemini extensions install</code>、<code>GEMINI.md</code> 这三样后面反复复用的东西。个人 / Pro / Ultra 账号日常请走 <a href="./antigravity.html">Antigravity CLI</a>，本页仍从 CLI 开讲，是因为它是概念入口，不是因为消费者还能用「Login with Google」。</li><li><strong>再学 <a href="./antigravity.html">Antigravity</a></strong>。它复用上面三个概念，再加上规则、技能、子智能体。2026-06-18 之后，这是个人开发者的日常入口。跳过 CLI 直接看它，你会在「这个配置文件是什么」上卡住。</li><li><strong>然后 <a href="./jules.html">Jules</a></strong>。它在「自主智能体」之上再叠一层 GitHub 仓库与 PR 工作流。</li><li><strong>动手时翻 <a href="./gemini-cookbook.html">Cookbook</a></strong>，查参数去 <a href="./gemini-cheatsheet.html">速查表</a>，概念记混了翻 <a href="./gemini-glossary.html">术语表</a>。</li><li>之后按需要看 Canvas / Flow / Code Assist / AI Studio / 订阅层级——它们互相独立，不构成链条。Flow 轴 A 零依赖，轴 B 对前端工程师相关度中高（对外讲功能时会用到），所以进「更多产品」，不进核心组。</li></ol><p><strong><a href="./code-assist.html">Code Assist</a> 排在后面不是因为它难</strong>，而是因为它的官方定位就是面向「有严格数据安全与合规要求的组织」，个人开发者通常不是第一需求。<strong><a href="./google-pro.html">订阅层级</a></strong> 放最后，因为它回答的是「我该为哪一档付钱」，等你知道自己要用哪个工具之后再看才有意义。</p><h2 id="快速决策" tabindex="-1">快速决策 <a class="header-anchor" href="#快速决策" aria-label="Permalink to &quot;快速决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的情况</th><th>用</th></tr></thead><tbody><tr><td>想在终端里试试 AI 编码</td><td><a href="./gemini-cli.html">Gemini CLI</a>（企业 / API key）或 <a href="./antigravity.html">Antigravity</a>（个人）</td></tr><tr><td>要改一个跨了五个模块的东西</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td>要把 React 从 18 升到 19</td><td><a href="./jules.html">Jules</a></td></tr><tr><td>不想离开 VS Code</td><td><a href="./code-assist.html">Code Assist</a></td></tr><tr><td>想让 AI 通读整个仓库做审计</td><td><a href="./ai-studio.html">AI Studio</a></td></tr><tr><td>半小时内要给产品经理看个原型</td><td><a href="./canvas.html">Canvas</a></td></tr><tr><td>落地页 / 宣传片 / 产品演示要出视频</td><td><a href="./flow.html">Google Flow</a></td></tr><tr><td>想知道免费额度够不够用</td><td><a href="./google-pro.html">订阅层级</a></td></tr></tbody></table><h2 id="共享的概念" tabindex="-1">共享的概念 <a class="header-anchor" href="#共享的概念" aria-label="Permalink to &quot;共享的概念&quot;">​</a></h2><p>家族内部有几样东西是跨产品复用的，先认识它们能省很多重复学习：</p><table tabindex="0"><thead><tr><th>概念</th><th>跨哪些产品</th></tr></thead><tbody><tr><td><code>GEMINI.md</code></td><td>Gemini CLI、Antigravity（全局规则）</td></tr><tr><td><code>AGENTS.md</code></td><td>Jules</td></tr><tr><td>MCP</td><td>Gemini CLI、Antigravity、Code Assist</td></tr><tr><td>订阅额度</td><td>一份订阅同时影响多个产品的可用量</td></tr><tr><td>Flow 积分</td><td>只用于 <a href="./flow.html">Google Flow</a>；与 Flow Music、Antigravity 的 AI credits 不是同一本账</td></tr></tbody></table><p>各自的准确路径与区别见<a href="./gemini-glossary.html">术语表</a>和<a href="./gemini-cheatsheet.html#配置速查">速查表的配置速查</a>。</p><h2 id="订阅与额度" tabindex="-1">订阅与额度 <a class="header-anchor" href="#订阅与额度" aria-label="Permalink to &quot;订阅与额度&quot;">​</a></h2><p>订阅分为 AI Plus / AI Pro / AI Ultra 5x / AI Ultra 20x 四档，<strong>不是两档</strong>。各档的模型倍数、存储、Google Cloud 额度见<a href="./gemini-cheatsheet.html#订阅层级">速查表的订阅层级</a>，本页不重复。Flow 的日 / 月积分见 <a href="./flow.html#额度">Flow</a>。Pro 里和编码相关的权益清单见 <a href="./google-pro.html">订阅页</a>。</p><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></li><li><a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档</a></li><li><a href="https://jules.google/docs/" target="_blank" rel="noreferrer">Jules 文档</a></li><li><a href="https://developers.google.com/gemini-code-assist/docs/overview" target="_blank" rel="noreferrer">Code Assist 文档</a></li><li><a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini API 模型清单</a></li><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Google Flow</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益</a></li><li><a href="https://one.google.com/about/google-ai-plans/" target="_blank" rel="noreferrer">Google AI 订阅对比</a></li></ul>`,32)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
